import { Component, inject, signal, computed, resource } from '@angular/core';
import { DatePipe } from '@angular/common';
import { Router } from '@angular/router';
import { SolicitudService } from '../../../../shared/services/solicitud.service';
import { UserService } from '../../../../services/user.service';
import { ToastService } from '../../../../shared/services/toast.service';
import { NavigationHistoryService } from '../../../../services/navigation-history.service';
import {
  resolveStatusColors,
  type BootstrapColorVar,
} from '../../../../shared/theme-chart-colors';
import {
  machoteBadgeTexto,
  machoteBadgeClass,
} from '../../../../shared/utils/machote-badge.util';
import type {
  Solicitud,
  AsignacionesStats,
} from '../../../../shared/models/solicitud.model';
import { PaginatorComponent } from '../../../../shared/components/paginator/paginator.component';
import { VdinChartComponent } from '../../../../shared/components/vdin-chart/vdin-chart.component';
import { type ChartData, type ChartOptions } from 'chart.js';
import { firstValueFrom } from 'rxjs';

const STATUS_VAR_MAP: Record<string, BootstrapColorVar> = {
  Enviada: '--bs-primary',
  Incompleta: '--bs-secondary',
  Subsanada: '--bs-warning',
  'En Análisis': '--bs-warning',
  'En Firma': '--bs-info',
  Terminada: '--bs-success',
  Aprobada: '--bs-success',
  'No Autorizada': '--bs-danger',
  'No Presentada': '--bs-secondary',
};

@Component({
  selector: 'app-seguimiento-asignaciones',
  imports: [DatePipe, PaginatorComponent, VdinChartComponent],
  templateUrl: './seguimiento-asignaciones.component.html',
  styleUrl: './seguimiento-asignaciones.component.scss',
})
export class SeguimientoAsignacionesComponent {
  private readonly router = inject(Router);
  private readonly solicitudService = inject(SolicitudService);
  private readonly userService = inject(UserService);
  private readonly toastService = inject(ToastService);
  private readonly navHistory = inject(NavigationHistoryService);

  readonly searchTerm = signal('');
  readonly selectedEvaluadorFilter = signal<string>('');
  readonly statusFilter = signal('Todos');
  readonly showFilters = signal(false);
  readonly dateFrom = signal('');
  readonly dateTo = signal('');
  readonly page = signal(1);
  readonly perPage = signal(15);
  readonly isActionLoading = signal(false);
  readonly solicitudAReasignar = signal<Solicitud | null>(null);
  readonly nuevoEvaluadorId = signal<number | null>(null);
  readonly solicitudADesasignar = signal<Solicitud | null>(null);

  readonly evaluadoresResource = resource({
    loader: async () => {
      const result = await firstValueFrom(
        this.userService.getUsers({ role: 'ejecutivo', perPage: 100 }),
      );
      return result.users;
    },
  });

  readonly statsResource = resource({
    loader: async () => {
      return firstValueFrom(this.solicitudService.getAsignacionesStats());
    },
  });

  readonly evaluadores = computed(() =>
    this.evaluadoresResource.hasValue() ? this.evaluadoresResource.value()! : [],
  );

  readonly stats = computed<AsignacionesStats | null>(() =>
    this.statsResource.hasValue() ? this.statsResource.value()! : null,
  );

  readonly isStatsLoading = computed(() => this.statsResource.isLoading());

  readonly kpis = computed(() => {
    const s = this.stats();
    return {
      total_asignadas: s?.kpis?.total_asignadas ?? 0,
      en_proceso: s?.kpis?.en_proceso ?? 0,
      terminadas: s?.kpis?.terminadas ?? 0,
      sin_asignar: s?.kpis?.sin_asignar ?? 0,
    };
  });

  readonly statusChartData = computed<ChartData<'doughnut'>>(() => {
    const byStatus = this.stats()?.by_status ?? [];
    const labels = byStatus.map((item) => item.status);
    const data = byStatus.map((item) => item.count);

    if (labels.length === 0) {
      return { labels: [], datasets: [] };
    }

    const { backgroundColor, borderColor } = resolveStatusColors(labels, 'doughnut');

    return {
      labels,
      datasets: [
        {
          data,
          backgroundColor,
          borderColor,
          borderWidth: 1,
          hoverOffset: 4,
          ...( {
            __colorVars: labels.map((l) => STATUS_VAR_MAP[l] ?? '--bs-secondary'),
          } as Record<string, unknown> ),
        },
      ],
    };
  });

  readonly evaluadoresChartData = computed<ChartData<'bar'>>(() => {
    const byEvaluador = this.stats()?.by_evaluador ?? [];
    const labels = byEvaluador.map((item) => item.name);
    const enProcesoData = byEvaluador.map((item) => item.en_proceso);
    const terminadasData = byEvaluador.map((item) => item.terminadas);

    if (labels.length === 0) {
      return { labels: [], datasets: [] };
    }

    return {
      labels,
      datasets: [
        {
          label: 'En Proceso',
          data: enProcesoData,
          backgroundColor: 'rgba(13, 110, 253, 0.7)',
          borderColor: 'rgb(13, 110, 253)',
          borderWidth: 1,
          ...( {
            __colorVars: ['--bs-primary'],
          } as Record<string, unknown> ),
        },
        {
          label: 'Terminadas',
          data: terminadasData,
          backgroundColor: 'rgba(25, 135, 84, 0.7)',
          borderColor: 'rgb(25, 135, 84)',
          borderWidth: 1,
          ...( {
            __colorVars: ['--bs-success'],
          } as Record<string, unknown> ),
        },
      ],
    };
  });

  readonly doughnutChartOptions: ChartOptions<'doughnut'> = {
    responsive: true,
    maintainAspectRatio: false,
    cutout: '70%',
    plugins: {
      legend: {
        display: false,
      },
      tooltip: {
        callbacks: {
          label: (ctx) => ` ${ctx.label}: ${ctx.formattedValue} solicitudes`,
        },
      },
    },
  };

  readonly barChartOptions: ChartOptions<'bar'> = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top',
        align: 'end',
        labels: {
          usePointStyle: true,
          pointStyle: 'circle',
          boxWidth: 8,
          padding: 10,
          font: { size: 11, weight: 500 },
        },
      },
    },
    scales: {
      x: {
        stacked: true,
        ticks: { font: { size: 11 }, maxRotation: 25 },
        grid: { display: false },
      },
      y: {
        stacked: true,
        beginAtZero: true,
        ticks: { precision: 0, font: { size: 11 } },
      },
    },
  };

  statusColor(status: string): string {
    const varName = STATUS_VAR_MAP[status] ?? '--bs-secondary';
    return `var(${varName})`;
  }

  readonly queryParams = computed(() => ({
    tipo: 'tramite' as const,
    search: this.searchTerm().trim() || undefined,
    status: this.statusFilter() === 'Todos' ? undefined : this.statusFilter(),
    evaluadorId: this.selectedEvaluadorFilter() ? Number(this.selectedEvaluadorFilter()) : undefined,
    dateFrom: this.dateFrom() || undefined,
    dateTo: this.dateTo() || undefined,
    page: this.page(),
    perPage: this.perPage(),
    conEvaluador: true,
  }));

  readonly solicitudesResource = resource({
    params: () => this.queryParams(),
    loader: async ({ params }) => {
      return firstValueFrom(this.solicitudService.getSolicitudes(params));
    },
  });

  readonly solicitudes = computed(() =>
    this.solicitudesResource.hasValue() ? this.solicitudesResource.value()!.data : [],
  );

  readonly paginationMeta = computed(() => {
    const v = this.solicitudesResource.value();
    return v
      ? { currentPage: v.current_page, lastPage: v.last_page, total: v.total, perPage: v.per_page }
      : { currentPage: 1, lastPage: 1, total: 0, perPage: 15 };
  });

  readonly isLoading = computed(() => this.solicitudesResource.isLoading());

  onSearchInput(event: Event): void {
    this.searchTerm.set((event.target as HTMLInputElement).value);
    this.page.set(1);
  }

  onEvaluadorFilterChange(event: Event): void {
    this.selectedEvaluadorFilter.set((event.target as HTMLSelectElement).value);
    this.page.set(1);
  }

  onStatusChange(event: Event): void {
    this.statusFilter.set((event.target as HTMLSelectElement).value);
    this.page.set(1);
  }

  toggleFilters(): void {
    this.showFilters.update((visible) => !visible);
  }

  onDateFromChange(event: Event): void {
    this.dateFrom.set((event.target as HTMLInputElement).value);
    this.page.set(1);
  }

  onDateToChange(event: Event): void {
    this.dateTo.set((event.target as HTMLInputElement).value);
    this.page.set(1);
  }

  clearFilters(): void {
    this.searchTerm.set('');
    this.selectedEvaluadorFilter.set('');
    this.statusFilter.set('Todos');
    this.dateFrom.set('');
    this.dateTo.set('');
    this.page.set(1);
  }

  onPageChange(page: number): void {
    this.page.set(page);
  }

  recargarTodo(): void {
    this.statsResource.reload();
    this.solicitudesResource.reload();
    this.evaluadoresResource.reload();
  }

  verDetalle(folio: string): void {
    this.navHistory.recordBackPath('tramites/seguimiento-asignaciones');
    this.router.navigate(['/ejecutivos/solicitudes', folio], {
      queryParams: { from: 'tramites/seguimiento-asignaciones' },
    });
  }

  abrirModalReasignar(solicitud: Solicitud): void {
    this.solicitudAReasignar.set(solicitud);
    this.nuevoEvaluadorId.set(null);
  }

  cerrarModalReasignar(): void {
    this.solicitudAReasignar.set(null);
    this.nuevoEvaluadorId.set(null);
  }

  onNuevoEvaluadorChange(event: Event): void {
    const val = Number((event.target as HTMLSelectElement).value);
    this.nuevoEvaluadorId.set(val || null);
  }

  async confirmarReasignacion(): Promise<void> {
    const solicitud = this.solicitudAReasignar();
    const nuevoId = this.nuevoEvaluadorId();
    if (!solicitud || !nuevoId) return;

    this.isActionLoading.set(true);
    try {
      await firstValueFrom(this.solicitudService.asignarEvaluador(solicitud.folio, nuevoId));
      this.toastService.success(`Solicitud ${solicitud.folio} reasignada con éxito.`);
      this.cerrarModalReasignar();
      this.solicitudesResource.reload();
      this.statsResource.reload();
    } catch {
      this.toastService.error('Ocurrió un error al reasignar el evaluador.');
    } finally {
      this.isActionLoading.set(false);
    }
  }

  abrirModalDesasignar(solicitud: Solicitud): void {
    this.solicitudADesasignar.set(solicitud);
  }

  cerrarModalDesasignar(): void {
    this.solicitudADesasignar.set(null);
  }

  async confirmarDesasignacion(): Promise<void> {
    const solicitud = this.solicitudADesasignar();
    if (!solicitud) return;

    this.isActionLoading.set(true);
    try {
      await firstValueFrom(this.solicitudService.desasignarEvaluador(solicitud.folio));
      this.toastService.success(`Asignación cancelada para ${solicitud.folio}.`);
      this.cerrarModalDesasignar();
      this.solicitudesResource.reload();
      this.statsResource.reload();
    } catch {
      this.toastService.error('Ocurrió un error al cancelar la asignación.');
    } finally {
      this.isActionLoading.set(false);
    }
  }

  machoteBadgeTexto = machoteBadgeTexto;
  machoteBadgeClass = machoteBadgeClass;

  statusBadgeClass(status: string): string {
    switch (status) {
      case 'Enviada':
        return 'bg-info text-dark';
      case 'En Análisis':
        return 'bg-primary-subtle text-primary border border-primary';
      case 'Incompleta':
        return 'bg-secondary';
      case 'Subsanada':
        return 'bg-warning text-dark';
      case 'En Firma':
        return 'bg-warning-subtle text-warning border border-warning';
      case 'Terminada':
      case 'Aprobada':
        return 'bg-success';
      case 'No Autorizada':
      case 'No Aprobada':
        return 'bg-danger';
      default:
        return 'bg-secondary';
    }
  }
}
